public class InnerGatewayGatewayInterceptorConfigurationFactory(Action<Humidifier.BedrockAgentCore.GatewayTypes.GatewayInterceptorConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.GatewayTypes.GatewayInterceptorConfiguration>
{

    internal InnerGatewayInterceptorConfigurationFactory InterceptorFactory { get; set; }

    internal InnerGatewayInterceptorInputConfigurationFactory InputConfigurationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.GatewayTypes.GatewayInterceptorConfiguration Create()
    {
        var gatewayInterceptorConfigurationResult = CreateGatewayInterceptorConfiguration();
        factoryAction?.Invoke(gatewayInterceptorConfigurationResult);

        return gatewayInterceptorConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.GatewayTypes.GatewayInterceptorConfiguration CreateGatewayInterceptorConfiguration()
    {
        var gatewayInterceptorConfigurationResult = new Humidifier.BedrockAgentCore.GatewayTypes.GatewayInterceptorConfiguration();

        return gatewayInterceptorConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.GatewayTypes.GatewayInterceptorConfiguration result)
    {
        base.CreateChildren(result);

        result.Interceptor ??= InterceptorFactory?.Build();
        result.InputConfiguration ??= InputConfigurationFactory?.Build();
    }

} // End Of Class

